<?php require_once 'config/db.php';require_once 'includes/auth.php';require_role(['customer']);$u=$_SESSION['user'];$cart=$_SESSION['cart']??[];$err='';$items=[];$sub=0;$tax=0;foreach($cart as $id=>$q){$s=$conn->prepare('SELECT * FROM products WHERE id=?');$s->bind_param('i',$id);$s->execute();$p=$s->get_result()->fetch_assoc();if($p&&$q>0){$p['qty']=$q;$items[]=$p;$sub+=$p['price']*$q;$tax+=$p['price']*$q*$p['tax_rate']/100;}}$total=$sub+$tax;if(!$items){header('Location:cart.php?msg=Your+cart+is+empty');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){if(empty($_POST['confirm']))$err='Please confirm before placing this order.';else{$method=$_POST['method']??'Cash on Delivery';if(!in_array($method,['Cash on Delivery','Online'],true))$method='Cash on Delivery';$addr=trim($_POST['address']??$u['address']);foreach($items as $p){if($p['qty']>$p['stock']){$err='Stock changed for '.$p['name'].'. Please update your cart.';break;}}if(!$err){$conn->begin_transaction();try{$st='Pending';$s=$conn->prepare('INSERT INTO orders(customer_id,status,subtotal,tax,total,shipping_address) VALUES(?,?,?,?,?,?)');$s->bind_param('isddds',$u['id'],$st,$sub,$tax,$total,$addr);$s->execute();$oid=$conn->insert_id;foreach($items as $p){$s=$conn->prepare('INSERT INTO order_items(order_id,product_id,quantity,unit_price,tax_rate) VALUES(?,?,?,?,?)');$s->bind_param('iiidd',$oid,$p['id'],$p['qty'],$p['price'],$p['tax_rate']);$s->execute();$s=$conn->prepare('UPDATE products SET stock=stock-? WHERE id=? AND stock>=?');$s->bind_param('iii',$p['qty'],$p['id'],$p['qty']);$s->execute();if($s->affected_rows!==1)throw new Exception('Stock unavailable');}$payStatus=$method==='Online'?'Pending':'Pending';$s=$conn->prepare('INSERT INTO payments(order_id,method,amount,status) VALUES(?,?,?,?)');$s->bind_param('isds',$oid,$method,$total,$payStatus);$s->execute();$conn->commit();$_SESSION['cart']=[];header('Location:orders.php?msg=Order+placed+and+awaiting+confirmation');exit;}catch(Throwable $e){$conn->rollback();$err='Could not place order. Please refresh your cart and try again.';}}}}include 'includes/header.php';?><div class="card"><h2>Confirm Your Order</h2><p>Review your items and confirm only if you want to place an order. Otherwise, go back to your cart; items will remain there.</p><?php if($err):?><div class="error"><?=h($err)?></div><?php endif;?><table><tr><th>Item</th><th>Qty</th><th>Price</th><th>Line total</th></tr><?php foreach($items as $p):?><tr><td><?=h($p['name'])?></td><td><?=$p['qty']?></td><td>₹<?=number_format($p['price'],2)?></td><td>₹<?=number_format($p['price']*$p['qty'],2)?></td></tr><?php endforeach;?></table><p>Subtotal: ₹<?=number_format($sub,2)?> | Tax: ₹<?=number_format($tax,2)?> | <b>Total: ₹<?=number_format($total,2)?></b></p><form method="post"><label>Shipping address</label><textarea name="address" required><?=h($u['address'])?></textarea><label>Payment method</label><select name="method"><option>Cash on Delivery</option><option>Online</option></select><p class="muted">Online payment is a demo placeholder and does not charge money. Payment remains pending until processed externally.</p><label><input type="checkbox" name="confirm" value="1" required style="width:auto"> I confirm that I want to place this order.</label><button class="btn success">Confirm & Place Order</button> <a class="btn" href="cart.php">Back to Cart</a></form></div><?php include 'includes/footer.php';?>